
const cfg = window.APP_CONFIG || {};
const configured = cfg.SUPABASE_URL && !cfg.SUPABASE_URL.includes("COLE_AQUI") &&
                   cfg.SUPABASE_ANON_KEY && !cfg.SUPABASE_ANON_KEY.includes("COLE_AQUI");
const sb = configured ? supabase.createClient(cfg.SUPABASE_URL, cfg.SUPABASE_ANON_KEY) : null;

let materials = [];
let inventories = [];
let currentInventory = null;
let currentItems = new Map();

const BUILTIN_EQUIPMENT_IMAGES = {"GERAL":"data:image/jpeg;base64,","D8T":"data:image/jpeg;base64,","844L":"data:image/jpeg;base64,","336":"data:image/jpeg;base64,","374":"data:image/jpeg;base64,","50VX":"data:image/jpeg;base64,","924K":"data:image/jpeg;base64,","724K":"data:image/jpeg;base64,","374DL":"data:image/jpeg;base64,","ATEGO 1719":"data:image/jpeg;base64,","ACTROS 4844":"data:image/jpeg;base64,","416E":"data:image/jpeg;base64,","670G":"data:image/jpeg;base64,","350G LC":"data:image/jpeg;base64,","OUTROS":"data:image/jpeg;base64,"};
let equipmentCatalog = [];
let selectedEquipmentId = null;

function normalizeModelKey(v){
  return String(v||"").toUpperCase().replace(/\s+/g," ").trim().replace(/^844 L$/,"844L");
}

function fallbackEquipmentImage(model){
  const key=normalizeModelKey(model);
  return BUILTIN_EQUIPMENT_IMAGES[key] || BUILTIN_EQUIPMENT_IMAGES.OUTROS || BUILTIN_EQUIPMENT_IMAGES.GERAL;
}


const $ = id => document.getElementById(id);
const n = v => Number(v ?? 0);
const fmt = v => new Intl.NumberFormat("pt-BR", {maximumFractionDigits:2}).format(n(v));

function toast(msg){
  $("toast").textContent = msg;
  $("toast").classList.add("show");
  setTimeout(()=>$("toast").classList.remove("show"),2600);
}

function calc(m, counted){
  if (counted === null || counted === undefined || counted === "") return {status:"PENDENTE", qty:0};
  const q=n(counted), min=n(m.min_stock), target=n(m.target_stock), mult=Math.max(n(m.purchase_multiple),1);
  if(q < min){
    return {status:"COMPRAR", qty: Math.ceil(Math.max(target-q,0)/mult)*mult};
  }
  return {status:"OK", qty:0};
}

async function boot(){
  if(!sb){
    $("connectionBadge").textContent="Configuração pendente";
    toast("Preencha config.js com URL e chave do Supabase.");
    return;
  }
  $("connectionBadge").textContent="Supabase conectado";
  await Promise.all([loadMaterials(), loadInventories()]);
  await loadEquipmentCatalog();
  renderEquipmentCards();
  renderHistory();
  refreshPurchaseSelect();
}

async function loadMaterials(){
  const {data,error}=await sb.from("materials").select("*").eq("active",true).order("material_code");
  if(error){toast(error.message);return}
  materials=data||[];
}

async function loadEquipmentCatalog(){
  const [{data:eqData,error:eqError},{data:linkData,error:linkError}] = await Promise.all([
    sb.from("equipment_catalog").select("*").eq("active",true).order("model"),
    sb.from("equipment_materials").select("equipment_id,material_id")
  ]);

  if(eqError){
    toast("Cadastros de equipamentos ainda não configurados no Supabase.");
    equipmentCatalog=[{
      id:"geral",model:"GERAL",tags:["TODOS OS EQUIPAMENTOS"],materials:null,
      image:fallbackEquipmentImage("GERAL"),general:true
    }];
    return;
  }
  if(linkError){toast(linkError.message);return}

  const materialCodeById=new Map(materials.map(m=>[m.id,String(m.material_code)]));
  const linksByEquipment=new Map();
  (linkData||[]).forEach(link=>{
    const code=materialCodeById.get(link.material_id);
    if(!code) return;
    if(!linksByEquipment.has(link.equipment_id)) linksByEquipment.set(link.equipment_id,[]);
    linksByEquipment.get(link.equipment_id).push(code);
  });

  equipmentCatalog=[{
    id:"geral",
    model:"GERAL",
    tags:["TODOS OS EQUIPAMENTOS"],
    materials:null,
    image:fallbackEquipmentImage("GERAL"),
    general:true
  }, ...(eqData||[]).map(eq=>({
    id:eq.id,
    dbId:eq.id,
    model:eq.model,
    tags:Array.isArray(eq.tags)?eq.tags:[],
    materials:linksByEquipment.get(eq.id)||[],
    image:eq.image_data || fallbackEquipmentImage(eq.model),
    general:false
  }))];
}


async function loadInventories(){
  const {data,error}=await sb.from("inventories").select("*").order("created_at",{ascending:false});
  if(error){toast(error.message);return}
  inventories=data||[];
}

function tabs(){
  document.querySelectorAll(".tabs button").forEach(b=>b.onclick=async()=>{
    document.querySelectorAll(".tabs button").forEach(x=>x.classList.remove("active"));
    document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));
    b.classList.add("active"); $("tab-"+b.dataset.tab).classList.add("active");
    if(b.dataset.tab==="historico"){await loadInventories();renderHistory()}
    if(b.dataset.tab==="compras"){await loadInventories();refreshPurchaseSelect()}
  });
}

async function startInventory(){
  const responsible=$("responsible").value.trim();
  if(!responsible){toast("Informe o responsável.");return}
  const payload={responsible,area:$("area").value.trim(),notes:$("notes").value.trim()};
  const {data,error}=await sb.from("inventories").insert(payload).select().single();
  if(error){toast(error.message);return}
  currentInventory=data;
  const rows=materials.map(m=>({inventory_id:data.id,material_id:m.id}));
  const {error:itemErr}=await sb.from("inventory_items").insert(rows);
  if(itemErr){toast(itemErr.message);return}
  await loadCurrentItems();
  $("inventoryWorkspace").classList.remove("hidden");
  $("finishInventory").disabled=false;
  $("inventoryMeta").textContent=`#${data.id.slice(0,8)} • ${data.responsible} • ${new Date().toLocaleDateString("pt-BR")}`;
  renderInventory();
  toast("Inventário iniciado.");
}

async function loadCurrentItems(){
  const {data,error}=await sb.from("inventory_items").select("*").eq("inventory_id",currentInventory.id);
  if(error){toast(error.message);return}
  currentItems=new Map((data||[]).map(x=>[x.material_id,x]));
}

async function saveCount(materialId,value,obs){
  const qty=value===""?null:n(value);
  const row=currentItems.get(materialId);
  const payload={counted_qty:qty,observation:obs||null,checked_at:qty===null?null:new Date().toISOString()};
  const {data,error}=await sb.from("inventory_items").update(payload).eq("id",row.id).select().single();
  if(error){toast(error.message);return}
  currentItems.set(materialId,data);
  renderInventory($("searchMaterial").value);
}

function renderInventory(filter=""){
  const term=filter.trim().toLowerCase();
  const list=materials.filter(m=>(m.material_code+" "+m.description).toLowerCase().includes(term));
  $("materialList").innerHTML=list.map(m=>{
    const item=currentItems.get(m.id)||{};
    const c=item.counted_qty;
    const r=calc(m,c);
    const cls=r.status==="OK"?"ok":r.status==="COMPRAR"?"buy":"pending";
    return `<div class="card">
      <div class="card-head"><div><div class="code">${m.material_code}</div><div class="desc">${m.description}</div></div><span class="tag">${m.type}</span></div>
      <div class="row">
        <label>Qtd. 2025<input value="${m.consumption_2025}" disabled></label>
        <label>Mínimo<input value="${fmt(m.min_stock)}" disabled></label>
        <label>Alvo<input value="${fmt(m.target_stock)}" disabled></label>
        <label>Qtd. contada<input class="count" inputmode="decimal" data-id="${m.id}" value="${c??""}" placeholder="0"></label>
      </div>
      <label style="margin-top:8px">Observação<input class="obs" data-id="${m.id}" value="${item.observation??""}" placeholder="Opcional"></label>
      <div class="status ${cls}">${r.status}${r.status==="COMPRAR" ? ` • sugestão: ${fmt(r.qty)}`:""}</div>
    </div>`;
  }).join("");

  document.querySelectorAll(".count").forEach(inp=>inp.onchange=()=>{
    const obs=document.querySelector(`.obs[data-id="${inp.dataset.id}"]`)?.value||"";
    saveCount(inp.dataset.id,inp.value,obs);
  });
  document.querySelectorAll(".obs").forEach(inp=>inp.onchange=()=>{
    const count=document.querySelector(`.count[data-id="${inp.dataset.id}"]`)?.value||"";
    saveCount(inp.dataset.id,count,inp.value);
  });

  const all=materials.map(m=>({m,item:currentItems.get(m.id)||{}}));
  const checked=all.filter(x=>x.item.counted_qty!==null && x.item.counted_qty!==undefined).length;
  const buy=all.filter(x=>calc(x.m,x.item.counted_qty).status==="COMPRAR").length;
  $("kpiTotal").textContent=materials.length;
  $("kpiChecked").textContent=checked;
  $("kpiPending").textContent=materials.length-checked;
  $("kpiBuy").textContent=buy;
}

async function finishInventory(){
  const pending=materials.filter(m=>{
    const i=currentItems.get(m.id)||{};
    return i.counted_qty===null || i.counted_qty===undefined;
  }).length;
  if(pending){toast(`Ainda existem ${pending} itens sem conferência.`);return}
  const responsible=$("responsible").value.trim();
  if(!responsible){toast("Informe o responsável.");return}
  const payload={
    responsible,
    area:$("area").value.trim(),
    notes:$("notes").value.trim(),
    status:"finished",
    finished_at:new Date().toISOString()
  };
  const {error}=await sb.from("inventories").update(payload).eq("id",currentInventory.id);
  if(error){toast(error.message);return}
  toast("Inventário finalizado. Relatório de compra atualizado.");
  await loadInventories();
  refreshPurchaseSelect(currentInventory.id);
  document.querySelector('[data-tab="compras"]').click();
}

function renderEquipmentCards(filter=""){
  const term=filter.trim().toLowerCase();
  const list=equipmentCatalog.filter(eq=>{
    const hay=(eq.model+" "+eq.tags.join(" ")).toLowerCase();
    return hay.includes(term);
  });

  $("equipmentGrid").innerHTML=list.map(eq=>{
    const count=eq.general ? materials.length : eq.materials.length;
    return `<button type="button" class="equipment-card ${eq.general?'equipment-card-general':''}" data-equipment="${eq.id}">
      <div class="equipment-image-wrap">
        <img class="equipment-image" src="${eq.image}" alt="${eq.model}" loading="lazy">
        ${eq.general?'<span class="equipment-general-badge">VISÃO COMPLETA</span>':''}
      </div>
      <div class="equipment-card-body">
        <div class="equipment-model">${eq.model}</div>
        <div class="equipment-tags">${eq.tags.map(t=>`<span>${t}</span>`).join("")}</div>
        <div class="equipment-count">${count} ${count===1?'material':'materiais'}</div>
      </div>
    </button>`;
  }).join("") || `<div class="empty-state">Nenhum equipamento encontrado.</div>`;

  document.querySelectorAll('.equipment-card[data-equipment]').forEach(card=>{
    card.onclick=()=>openEquipmentParams(card.dataset.equipment);
  });
}

function openEquipmentParams(id){
  const eq=equipmentCatalog.find(x=>x.id===id);
  if(!eq) return;
  selectedEquipmentId=id;
  $("equipmentParamsView").classList.add("hidden");
  $("equipmentMaterialsView").classList.remove("hidden");
  $("searchParams").value="";

  const count=eq.general ? materials.length : eq.materials.length;
  $("selectedEquipmentHeader").innerHTML=`
    <img src="${eq.image}" alt="${eq.model}">
    <div>
      <div class="selected-equipment-kicker">Parâmetros por equipamento</div>
      <h2>${eq.model}</h2>
      <div class="equipment-tags selected-tags">${eq.tags.map(t=>`<span>${t}</span>`).join("")}</div>
      <div class="muted">${count} ${count===1?'material vinculado':'materiais vinculados'}</div>
    </div>`;
  renderParams();
}

function backToEquipmentParams(){
  selectedEquipmentId=null;
  $("equipmentMaterialsView").classList.add("hidden");
  $("equipmentParamsView").classList.remove("hidden");
  $("searchParams").value="";
  renderEquipmentCards($("searchEquipment").value);
}

function renderParams(filter=""){
  const eq=equipmentCatalog.find(x=>x.id===selectedEquipmentId);
  if(!eq){
    $("paramsList").innerHTML="";
    return;
  }

  const term=filter.trim().toLowerCase();
  const allowed=eq.general ? null : new Set(eq.materials);
  const list=materials.filter(m=>{
    if(allowed && !allowed.has(String(m.material_code))) return false;
    return (m.material_code+" "+m.description).toLowerCase().includes(term);
  });

  $("paramsList").innerHTML=list.length ? list.map(m=>`<div class="card param-material-card">
    <div class="card-head">
      <div>
        <div class="code">${m.material_code}</div>
        <div class="desc">${m.description}</div>
      </div>
      <span class="tag">Consumo 2025: ${m.consumption_2025}</span>
    </div>
    <div class="row three">
      <label>Estoque mínimo<input data-p="min_stock" data-id="${m.id}" type="number" min="0" step="1" value="${n(m.min_stock)}"></label>
      <label>Estoque-alvo<input data-p="target_stock" data-id="${m.id}" type="number" min="0" step="1" value="${n(m.target_stock)}"></label>
      <label>Múltiplo de compra<input data-p="purchase_multiple" data-id="${m.id}" type="number" min="1" step="1" value="${Math.max(n(m.purchase_multiple),1)}"></label>
    </div>
    <div class="param-card-actions">
      <button class="save-param primary" data-id="${m.id}">Salvar parâmetros</button>
      ${eq.general
        ? `<button class="danger-outline deactivate-material" data-id="${m.id}" type="button">Remover do inventário</button>`
        : `<button class="secondary unlink-material" data-id="${m.id}" data-equipment="${eq.dbId}" type="button">Remover deste equipamento</button>`}
    </div>
  </div>`).join("") : `<div class="empty-state">Nenhum material encontrado para este equipamento.</div>`;

  document.querySelectorAll(".save-param").forEach(btn=>btn.onclick=()=>saveParams(btn.dataset.id));
  document.querySelectorAll(".deactivate-material").forEach(btn=>btn.onclick=()=>deactivateMaterial(btn.dataset.id));
  document.querySelectorAll(".unlink-material").forEach(btn=>btn.onclick=()=>unlinkMaterialFromEquipment(btn.dataset.id,btn.dataset.equipment));
}
async function saveParams(id){
  const vals={};
  document.querySelectorAll(`[data-id="${id}"][data-p]`).forEach(x=>vals[x.dataset.p]=n(x.value));
  if(vals.target_stock < vals.min_stock){toast("O estoque-alvo deve ser maior ou igual ao mínimo.");return}
  const {data,error}=await sb.from("materials").update(vals).eq("id",id).select().single();
  if(error){toast(error.message);return}
  const ix=materials.findIndex(m=>m.id===id); if(ix>=0)materials[ix]=data;
  renderParams($("searchParams").value);
  if(currentInventory) renderInventory($("searchMaterial").value);
  toast("Parâmetros salvos.");
}


function escapeHtml(value){
  return String(value??"")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#039;");
}

function parseTags(value){
  return [...new Set(String(value||"")
    .split(/[,;\s]+/)
    .map(x=>x.trim().toUpperCase())
    .filter(Boolean))];
}

function openCatalogModal(title, subtitle, bodyHtml, footerHtml=""){
  $("catalogModalTitle").textContent=title;
  $("catalogModalSubtitle").textContent=subtitle||"";
  $("catalogModalBody").innerHTML=bodyHtml;
  $("catalogModalFooter").innerHTML=footerHtml;
  $("catalogModal").classList.remove("hidden");
}

function closeCatalogModal(){
  $("catalogModal").classList.add("hidden");
  $("catalogModalBody").innerHTML="";
  $("catalogModalFooter").innerHTML="";
}

function equipmentCheckboxes(selectedIds=[]){
  const selected=new Set((selectedIds||[]).map(String));
  const eqs=equipmentCatalog.filter(x=>!x.general);
  return eqs.length ? `<div class="selection-list">${eqs.map(eq=>`
    <label class="selection-item">
      <input type="checkbox" class="equipment-link-choice" value="${eq.dbId}" ${selected.has(String(eq.dbId))?"checked":""}>
      <span><strong>${escapeHtml(eq.model)}</strong><small>${eq.tags.map(escapeHtml).join(" • ")}</small></span>
    </label>`).join("")}</div>` : `<div class="empty-state compact">Nenhum equipamento cadastrado.</div>`;
}

function materialCheckboxes(selectedMaterialIds=[]){
  const selected=new Set((selectedMaterialIds||[]).map(String));
  return materials.length ? `<div class="selection-list selection-list-materials">${materials.map(m=>`
    <label class="selection-item">
      <input type="checkbox" class="material-link-choice" value="${m.id}" ${selected.has(String(m.id))?"checked":""}>
      <span><strong>${escapeHtml(m.material_code)}</strong><small>${escapeHtml(m.description)}</small></span>
    </label>`).join("")}</div>` : `<div class="empty-state compact">Nenhum material ativo cadastrado.</div>`;
}

async function imageFileToDataUrl(file){
  if(!file) return null;
  if(!file.type.startsWith("image/")) throw new Error("Selecione um arquivo de imagem.");
  const raw=await new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=()=>resolve(reader.result);
    reader.onerror=()=>reject(new Error("Não foi possível ler a imagem."));
    reader.readAsDataURL(file);
  });

  return await new Promise((resolve,reject)=>{
    const img=new Image();
    img.onload=()=>{
      const maxW=1000,maxH=650;
      const scale=Math.min(1,maxW/img.width,maxH/img.height);
      const canvas=document.createElement("canvas");
      canvas.width=Math.max(1,Math.round(img.width*scale));
      canvas.height=Math.max(1,Math.round(img.height*scale));
      const ctx=canvas.getContext("2d");
      ctx.drawImage(img,0,0,canvas.width,canvas.height);
      resolve(canvas.toDataURL("image/jpeg",0.82));
    };
    img.onerror=()=>reject(new Error("Imagem inválida."));
    img.src=raw;
  });
}

async function refreshCatalogViews(keepEquipmentId=null){
  await loadMaterials();
  await loadEquipmentCatalog();
  renderEquipmentCards($("searchEquipment")?.value||"");
  if(keepEquipmentId && equipmentCatalog.some(x=>x.id===keepEquipmentId)){
    openEquipmentParams(keepEquipmentId);
  }else if(selectedEquipmentId && equipmentCatalog.some(x=>x.id===selectedEquipmentId)){
    openEquipmentParams(selectedEquipmentId);
  }else{
    selectedEquipmentId=null;
  }
  if(currentInventory) renderInventory($("searchMaterial")?.value||"");
}

async function openNewMaterialModal(preselectedEquipmentId=null){
  const pwd=await requireAdminPassword("Cadastros protegidos","Digite a senha administrativa para adicionar ou remover materiais e equipamentos.");
  if(!pwd) return;

  const selected=preselectedEquipmentId && preselectedEquipmentId!=="geral" ? [preselectedEquipmentId] : [];
  openCatalogModal(
    "Adicionar material",
    "O material ficará disponível nos próximos inventários. Você também pode vinculá-lo aos equipamentos.",
    `<div class="catalog-form">
      <div class="catalog-form-grid">
        <label>Código do material<input id="newMaterialCode" inputmode="numeric" placeholder="Ex.: 149528"></label>
        <label>Tipo<input id="newMaterialType" value="PD" placeholder="PD"></label>
        <label class="span-2">Descrição<input id="newMaterialDescription" placeholder="Descrição completa do material"></label>
        <label>Consumo 2025<input id="newMaterialConsumption" type="number" min="0" step="1" value="0"></label>
        <label>Estoque mínimo<input id="newMaterialMin" type="number" min="0" step="1" value="0"></label>
        <label>Estoque-alvo<input id="newMaterialTarget" type="number" min="0" step="1" value="0"></label>
        <label>Múltiplo de compra<input id="newMaterialMultiple" type="number" min="1" step="1" value="1"></label>
      </div>
      <div class="catalog-section-title">Vincular aos equipamentos</div>
      ${equipmentCheckboxes(selected)}
    </div>`,
    `<button id="cancelCatalogSave" type="button">Cancelar</button><button id="saveNewMaterial" class="primary" type="button">Salvar material</button>`
  );

  $("cancelCatalogSave").onclick=closeCatalogModal;
  $("saveNewMaterial").onclick=async()=>{
    const code=$("newMaterialCode").value.trim();
    const description=$("newMaterialDescription").value.trim();
    const type=$("newMaterialType").value.trim()||"PD";
    const consumption=n($("newMaterialConsumption").value);
    const min=n($("newMaterialMin").value);
    const target=n($("newMaterialTarget").value);
    const multiple=Math.max(1,n($("newMaterialMultiple").value));
    const equipmentIds=[...document.querySelectorAll(".equipment-link-choice:checked")].map(x=>x.value);

    if(!code || !description){toast("Informe código e descrição do material.");return}
    if(target<min){toast("O estoque-alvo deve ser maior ou igual ao mínimo.");return}

    $("saveNewMaterial").disabled=true;
    const {error}=await sb.rpc("admin_save_material",{
      p_material_id:null,
      p_material_code:code,
      p_description:description,
      p_type:type,
      p_consumption_2025:Math.round(consumption),
      p_min_stock:min,
      p_target_stock:target,
      p_purchase_multiple:multiple,
      p_equipment_ids:equipmentIds,
      p_password:currentAdminPassword()
    });
    $("saveNewMaterial").disabled=false;
    if(error){toast(error.message);return}

    closeCatalogModal();
    await refreshCatalogViews(preselectedEquipmentId);
    toast("Material adicionado ao inventário.");
  };
}

async function openNewEquipmentModal(){
  const pwd=await requireAdminPassword("Cadastros protegidos","Digite a senha administrativa para adicionar ou remover materiais e equipamentos.");
  if(!pwd) return;

  openCatalogModal(
    "Adicionar equipamento",
    "Cadastre modelo, TAGs, imagem e os materiais que pertencem a este equipamento.",
    `<div class="catalog-form">
      <div class="catalog-form-grid">
        <label>Modelo<input id="newEquipmentModel" placeholder="Ex.: 950 GC"></label>
        <label>TAGs<input id="newEquipmentTags" placeholder="Ex.: 7040PC, 7041PC"></label>
        <label class="span-2">Imagem do equipamento
          <input id="newEquipmentImage" type="file" accept="image/*">
          <small class="field-help">Opcional. A imagem é reduzida automaticamente antes de salvar.</small>
        </label>
      </div>
      <div id="equipmentImagePreview" class="equipment-image-preview hidden"></div>
      <div class="catalog-section-title">Materiais deste equipamento</div>
      ${materialCheckboxes()}
    </div>`,
    `<button id="cancelCatalogSave" type="button">Cancelar</button><button id="saveNewEquipment" class="primary" type="button">Salvar equipamento</button>`
  );

  $("cancelCatalogSave").onclick=closeCatalogModal;
  $("newEquipmentImage").onchange=async e=>{
    const file=e.target.files?.[0];
    if(!file){$("equipmentImagePreview").classList.add("hidden");return}
    try{
      const preview=await imageFileToDataUrl(file);
      $("equipmentImagePreview").innerHTML=`<img src="${preview}" alt="Prévia do equipamento">`;
      $("equipmentImagePreview").dataset.image=preview;
      $("equipmentImagePreview").classList.remove("hidden");
    }catch(err){toast(err.message)}
  };

  $("saveNewEquipment").onclick=async()=>{
    const model=$("newEquipmentModel").value.trim();
    const tags=parseTags($("newEquipmentTags").value);
    const materialIds=[...document.querySelectorAll(".material-link-choice:checked")].map(x=>x.value);
    const imageData=$("equipmentImagePreview").dataset.image||null;

    if(!model){toast("Informe o modelo do equipamento.");return}
    if(!tags.length){toast("Informe ao menos uma TAG.");return}

    $("saveNewEquipment").disabled=true;
    const {error}=await sb.rpc("admin_save_equipment",{
      p_equipment_id:null,
      p_model:model,
      p_tags:tags,
      p_image_data:imageData,
      p_material_ids:materialIds,
      p_password:currentAdminPassword()
    });
    $("saveNewEquipment").disabled=false;
    if(error){toast(error.message);return}

    closeCatalogModal();
    await refreshCatalogViews();
    toast("Equipamento adicionado.");
  };
}

async function openManageEquipmentModal(){
  const pwd=await requireAdminPassword("Cadastros protegidos","Digite a senha administrativa para gerenciar equipamentos.");
  if(!pwd) return;

  const eqs=equipmentCatalog.filter(x=>!x.general);
  openCatalogModal(
    "Gerenciar equipamentos",
    "Remover aqui desativa o card sem apagar históricos ou materiais.",
    `<div class="manage-list">${eqs.map(eq=>`
      <div class="manage-row">
        <img src="${eq.image}" alt="${escapeHtml(eq.model)}">
        <div class="manage-row-main">
          <strong>${escapeHtml(eq.model)}</strong>
          <span>${eq.tags.map(escapeHtml).join(" • ")}</span>
          <small>${eq.materials.length} ${eq.materials.length===1?"material":"materiais"}</small>
        </div>
        <button class="danger-outline remove-equipment" data-id="${eq.dbId}" type="button">Remover</button>
      </div>`).join("")}</div>`,
    `<button id="closeManageEquipment" class="primary" type="button">Fechar</button>`
  );

  $("closeManageEquipment").onclick=closeCatalogModal;
  document.querySelectorAll(".remove-equipment").forEach(btn=>btn.onclick=async()=>{
    const eq=equipmentCatalog.find(x=>x.dbId===btn.dataset.id);
    if(!eq) return;
    if(!confirm(`Remover o equipamento ${eq.model} da tela de parâmetros?`)) return;
    const {error}=await sb.rpc("admin_set_equipment_active",{
      p_equipment_id:eq.dbId,
      p_active:false,
      p_password:currentAdminPassword()
    });
    if(error){toast(error.message);return}
    closeCatalogModal();
    await refreshCatalogViews();
    toast("Equipamento removido.");
  });
}

async function deactivateMaterial(materialId){
  const m=materials.find(x=>x.id===materialId);
  if(!m) return;
  const pwd=await requireAdminPassword("Cadastros protegidos","Digite a senha administrativa para remover materiais.");
  if(!pwd) return;
  if(!confirm(`Remover o material ${m.material_code} dos próximos inventários? O histórico será preservado.`)) return;

  const {error}=await sb.rpc("admin_set_material_active",{
    p_material_id:materialId,
    p_active:false,
    p_password:currentAdminPassword()
  });
  if(error){toast(error.message);return}

  await refreshCatalogViews(selectedEquipmentId);
  toast("Material removido dos próximos inventários.");
}

async function unlinkMaterialFromEquipment(materialId,equipmentId){
  const m=materials.find(x=>x.id===materialId);
  const eq=equipmentCatalog.find(x=>x.dbId===equipmentId);
  if(!m || !eq) return;
  const pwd=await requireAdminPassword("Cadastros protegidos","Digite a senha administrativa para alterar vínculos.");
  if(!pwd) return;
  if(!confirm(`Remover o material ${m.material_code} somente do equipamento ${eq.model}?`)) return;

  const {error}=await sb.rpc("admin_set_material_equipment_link",{
    p_material_id:materialId,
    p_equipment_id:equipmentId,
    p_linked:false,
    p_password:currentAdminPassword()
  });
  if(error){toast(error.message);return}

  await refreshCatalogViews(equipmentId);
  toast("Material removido deste equipamento.");
}

function renderHistory(){
  $("historyList").innerHTML=inventories.length?inventories.map(i=>`
    <div class="history-item">
      <div><strong>${new Date(i.inventory_date+"T12:00:00").toLocaleDateString("pt-BR")}</strong> • ${i.responsible}
      <div class="muted">${i.area||"Sem área"} • ${i.status==="finished"?"Finalizado":"Em aberto"}</div></div>
      <div class="history-actions">
        <button onclick="openReport('${i.id}')">Ver relatório</button>
        <button onclick="requestAdminAction('edit','${i.id}')">Editar</button>
        <button class="danger" onclick="requestAdminAction('delete','${i.id}')">Excluir</button>
      </div>
    </div>`).join(""):`<p class="muted">Nenhum inventário registrado.</p>`;
}

function refreshPurchaseSelect(preselect){
  const sel=$("purchaseInventorySelect");
  const finished=inventories.filter(i=>i.status==="finished");
  sel.innerHTML=finished.map(i=>`<option value="${i.id}">${new Date(i.inventory_date+"T12:00:00").toLocaleDateString("pt-BR")} • ${i.responsible}</option>`).join("");
  if(preselect) sel.value=preselect;
  if(sel.value) loadPurchaseReport(sel.value); else {$("purchaseTable").innerHTML="";$("purchaseSummary").textContent="Nenhum inventário finalizado."}
}

async function loadPurchaseReport(id){
  const {data,error}=await sb.from("v_inventory_report").select("*").eq("inventory_id",id).eq("purchase_status","COMPRAR").order("material_code");
  if(error){toast(error.message);return}
  const rows=data||[];
  const totalQty=rows.reduce((s,r)=>s+n(r.suggested_purchase_qty),0);
  $("purchaseSummary").textContent=`${rows.length} itens precisam de compra • ${fmt(totalQty)} unidades sugeridas`;
  $("purchaseTable").innerHTML=rows.length?rows.map(r=>`<tr>
    <td><strong>${r.material_code}</strong></td><td>${r.description}</td><td>${fmt(r.counted_qty)}</td>
    <td>${fmt(r.min_stock)}</td><td>${fmt(r.target_stock)}</td><td><strong>${fmt(r.suggested_purchase_qty)}</strong></td>
  </tr>`).join(""):`<tr><td colspan="6">Nenhum item abaixo do estoque mínimo.</td></tr>`;

  const inv=inventories.find(x=>x.id===id);
  if(inv){
    const date=new Date(inv.inventory_date+"T12:00:00").toLocaleDateString("pt-BR");
    $("printReportMeta").textContent=`Inventário: ${date} • Responsável: ${inv.responsible}${inv.area ? ` • Área: ${inv.area}` : ""}`;
  }else{
    $("printReportMeta").textContent="";
  }
}



let pendingAdminAction = null;
let pendingAdminResolver = null;

const ADMIN_SESSION_KEY = "inventario_admin_password_session_v3";

function getAdminSessionPassword(){
  try{
    return sessionStorage.getItem(ADMIN_SESSION_KEY);
  }catch(e){
    return null;
  }
}

function setAdminSessionPassword(pwd){
  try{
    sessionStorage.setItem(ADMIN_SESSION_KEY, pwd);
  }catch(e){
    window.__inventarioAdminPassword = pwd;
  }
}

function clearAdminSessionPassword(){
  try{sessionStorage.removeItem(ADMIN_SESSION_KEY)}catch(e){}
  window.__inventarioAdminPassword=null;
}

function currentAdminPassword(){
  return getAdminSessionPassword() || window.__inventarioAdminPassword || null;
}

function showAdminModal(action, inventoryId, title=null, text=null){
  pendingAdminAction = {kind:"inventory", action, inventoryId};
  $("adminPassword").value = "";
  $("adminModalTitle").textContent = title || (action==="delete" ? "Excluir inventário" : "Editar inventário");
  $("adminModalText").textContent = text || (action==="delete"
    ? "Digite a senha administrativa para liberar esta sessão e excluir o inventário."
    : "Digite a senha administrativa para liberar esta sessão e editar o inventário.");
  $("adminConfirm").className = action==="delete" ? "danger" : "primary";
  $("adminModal").classList.remove("hidden");
  setTimeout(()=>$("adminPassword").focus(),50);
}

async function requireAdminPassword(title="Ação administrativa",text="Digite a senha administrativa para continuar."){
  const existing=currentAdminPassword();
  if(existing) return existing;

  return await new Promise(resolve=>{
    pendingAdminResolver=resolve;
    pendingAdminAction={kind:"auth"};
    $("adminPassword").value="";
    $("adminModalTitle").textContent=title;
    $("adminModalText").textContent=text;
    $("adminConfirm").className="primary";
    $("adminModal").classList.remove("hidden");
    setTimeout(()=>$("adminPassword").focus(),50);
  });
}

window.requestAdminAction = async (action, inventoryId) => {
  const pwd = currentAdminPassword();

  if(pwd){
    if(action==="delete" && !window.confirm("Deseja excluir definitivamente este inventário?")){
      return;
    }
    await performAdminAction(action, inventoryId, pwd, true);
    return;
  }

  showAdminModal(action, inventoryId);
};

function closeAdminModal(cancelled=false){
  if(cancelled && pendingAdminAction?.kind==="auth" && pendingAdminResolver){
    pendingAdminResolver(null);
  }
  pendingAdminAction = null;
  pendingAdminResolver = null;
  $("adminPassword").value = "";
  $("adminModal").classList.add("hidden");
}

async function performAdminAction(action, inventoryId, pwd, authenticatedSession=false){
  try{
    if(action==="delete"){
      const {data,error} = await sb.rpc(
        "admin_delete_inventory",
        {p_inventory_id:inventoryId,p_password:pwd}
      );

      if(error) throw error;

      if(!data){
        if(authenticatedSession){
          clearAdminSessionPassword();
          toast("A autorização administrativa expirou. Tente novamente.");
        }else{
          toast("Senha incorreta.");
        }
        return false;
      }

      if(!authenticatedSession) setAdminSessionPassword(pwd);

      closeAdminModal();
      await loadInventories();
      renderHistory();
      refreshPurchaseSelect();
      toast("Inventário excluído.");
      return true;
    }

    const {data,error} = await sb.rpc(
      "admin_reopen_inventory",
      {p_inventory_id:inventoryId,p_password:pwd}
    );

    if(error) throw error;

    if(!data){
      if(authenticatedSession){
        clearAdminSessionPassword();
        toast("A autorização administrativa expirou. Tente novamente.");
      }else{
        toast("Senha incorreta.");
      }
      return false;
    }

    if(!authenticatedSession) setAdminSessionPassword(pwd);

    closeAdminModal();

    const inv = inventories.find(x=>x.id===inventoryId) ||
      (await sb.from("inventories").select("*").eq("id",inventoryId).single()).data;

    currentInventory = {...inv,status:"open",finished_at:null};
    $("responsible").value = currentInventory.responsible || "";
    $("area").value = currentInventory.area || "";
    $("notes").value = currentInventory.notes || "";

    await loadCurrentItems();

    $("inventoryWorkspace").classList.remove("hidden");
    $("finishInventory").disabled = false;
    $("inventoryMeta").textContent =
      `EDITANDO • ${currentInventory.responsible} • ${new Date(currentInventory.inventory_date+"T12:00:00").toLocaleDateString("pt-BR")}`;

    renderInventory();
    document.querySelector('[data-tab="inventario"]').click();
    toast("Inventário reaberto para edição.");
    return true;

  }catch(err){
    toast(err.message || "Não foi possível concluir a ação.");
    return false;
  }
}

$("adminCancel").onclick = ()=>closeAdminModal(true);

$("adminModal").onclick = e => {
  if(e.target.id==="adminModal") closeAdminModal(true);
};

$("adminConfirm").onclick = async () => {
  if(!pendingAdminAction) return;

  const pwd = $("adminPassword").value;
  if(!pwd){
    toast("Digite a senha administrativa.");
    return;
  }

  $("adminConfirm").disabled = true;
  try{
    if(pendingAdminAction.kind==="auth"){
      const {data,error}=await sb.rpc("admin_check_password",{p_password:pwd});
      if(error){toast(error.message);return}
      if(!data){toast("Senha incorreta.");return}
      setAdminSessionPassword(pwd);
      const resolve=pendingAdminResolver;
      closeAdminModal();
      if(resolve) resolve(pwd);
      return;
    }

    const {action,inventoryId} = pendingAdminAction;
    await performAdminAction(action, inventoryId, pwd, false);
  }finally{
    $("adminConfirm").disabled = false;
  }
};

$("adminPassword").addEventListener("keydown", e => {
  if(e.key==="Enter") $("adminConfirm").click();
});

window.openReport = id => {
  document.querySelector('[data-tab="compras"]').click();
  $("purchaseInventorySelect").value=id;
  loadPurchaseReport(id);
};

$("startInventory").onclick=startInventory;
$("finishInventory").onclick=finishInventory;
$("searchMaterial").oninput=e=>renderInventory(e.target.value);
$("searchEquipment").oninput=e=>renderEquipmentCards(e.target.value);
$("searchParams").oninput=e=>renderParams(e.target.value);
$("backToEquipmentParams").onclick=backToEquipmentParams;
$("addMaterialBtn").onclick=()=>openNewMaterialModal(null);
$("addEquipmentBtn").onclick=openNewEquipmentModal;
$("manageEquipmentBtn").onclick=openManageEquipmentModal;
$("addMaterialToEquipmentBtn").onclick=()=>openNewMaterialModal(selectedEquipmentId);
$("catalogModalClose").onclick=closeCatalogModal;
$("catalogModal").onclick=e=>{if(e.target.id==="catalogModal") closeCatalogModal()};
$("purchaseInventorySelect").onchange=e=>loadPurchaseReport(e.target.value);
$("printReport").onclick=()=>window.print();
tabs();
boot();
